"""Reproducible, deliberately approximate PD-only shoulder teaching overlays.
Source MRI/labels are never rewritten. Coordinates are source JPEG pixels,
reviewed on each listed frame; no interpolation or propagation to unseen slices.
"""
import json, math
from pathlib import Path
R=Path(__file__).resolve().parents[1]; A=R/'app/src/main/assets'
D=json.loads((A/'shoulder-mri-data.json').read_text()); L=json.loads((A/'shoulder-mri-labels.json').read_text())
GROUPS=[{'id':14301,'name':'Сумки · протяжённые ориентиры PD','default':True,'icon':'wrist-mri-source/group-1252.png'}, {'id':14302,'name':'Аксиллярный карман · капсула и прикрепления','default':False,'icon':'wrist-mri-source/group-1259.png'}]
NOTES={
1601:'Акромиально-ключичная связка укрепляет капсулу АКС. Верхние и задние волокна участвуют в горизонтальной стабилизации. Общая исходная метка не разделяет отдельные пучки.',
1604:'Трапециевидная часть клювовидно-ключичной связки: от верхней поверхности клювовидного отростка к трапециевидной линии нижней поверхности ключицы; расположена латеральнее и кпереди от конической части.',
1605:'Коническая часть клювовидно-ключичной связки: от основания клювовидного отростка к коническому бугорку ключицы. Медиальнее и кзади от трапециевидной части.',
1596:'Клювовидно-акромиальная связка соединяет клювовидный отросток с акромионом и образует крышу над вращательной манжетой. Под ней находится подакромиальная часть SA–SD-сумки.',
1620:'Клювовидно-плечевая связка (CHL): от латеральной поверхности основания клювовидного отростка к области большого и малого бугорков с вплетением в капсулу и сухожилия манжеты. Участвует в формировании ротаторного интервала и удерживающего комплекса длинной головки бицепса. Отдельные порции в этом наборе не выделены.',
9863:'Верхняя суставно-плечевая связка (SGHL): от верхней области суставной впадины/верхней губы к верхней части малого бугорка. Входит в удерживающий комплекс сухожилия длинной головки бицепса вместе с CHL и прилежащими волокнами манжеты. Лучше оценивается на верхних аксиальных и сагиттальных срезах; точка не очерчивает всю связку.',
9864:'Средняя суставно-плечевая связка (MGHL): от передневерхней области суставной впадины к передней поверхности анатомической шейки плечевой кости, глубже сухожилия подлопаточной мышцы. Выраженно вариабельна, может быть тонкой или отсутствовать. Её нельзя принимать за оторванную губу.',
9865:'Нижний суставно-плечевой связочный комплекс (IGHL) включает передний пучок, задний пучок и промежуточную аксиллярную часть капсулы. Исходная общая точка не доказывает визуализацию каждого компонента. Для учебных ориентиров открой отдельную группу «Аксиллярный карман».',
1597:'Верхняя поперечная связка лопатки перекрывает вырезку лопатки. Надлопаточный нерв обычно проходит под ней, артерия — над ней. В этом модуле отмечена общая область, не отдельные волокна.',
1621:'Область поперечного удерживающего комплекса межбугорковой борозды. Самостоятельная «поперечная связка плеча» описывается не всеми авторами: значительную часть покрова образуют продолжающиеся волокна подлопаточной мышцы, CHL и прилежащей манжеты. Исходное название сохранено; не путать с внутрисуставным pulley-комплексом.',
2380:'Подакромиальная и поддельтовидная части обычно образуют единую SA–SD-сумку между манжетой и акромионом/клювовидно-акромиальной дугой/дельтовидной мышцей. На PD вместо исходной точки используется ориентировочная протяжённая зона; это не контур жидкости.',
2384:'Исходная метка подлопаточной подсухожильной области. Подлопаточный суставной карман и отдельная подсухожильная сумка описываются неодинаково и могут сообщаться. Без отчётливого прослеживания сообщения на этом неартрографическом наборе их нельзя достоверно разделить. Не смешивать с подклювовидной сумкой, лежащей поверхностнее сухожилия подлопаточной мышцы.'
}
ST={
143101:('≈ SA–SD · подакромиальная и поддельтовидная сумка',14301,'organs','Единая подакромиально-поддельтовидная (SA–SD) сумка: под акромионом и клювовидно-акромиальной связкой, поверх сухожилий вращательной манжеты, с латеральным продолжением глубже дельтовидной мышцы. Цветная лента показывает ожидаемую плоскость скольжения, а не толщину сумки, объём жидкости или бурсит. Не сообщается в норме с полостью плечевого сустава.'),
143102:('≈ Подклювовидная сумка · ожидаемая область',14301,'organs','Ожидаемая область подклювовидной сумки: кпереди от сухожилия подлопаточной мышцы, под клювовидным отростком и позади объединённого сухожилия короткой головки бицепса и клювовидно-плечевой мышцы. Лента — топографический ориентир; отдельная стенка и жидкость здесь достоверно не сегментированы. Это не подлопаточный суставной карман.'),
143103:('≈ Подлопаточная подсухожильная область',14301,'organs',NOTES[2384]+' Цветной ориентир расположен глубже сухожилия; сообщение с суставом и граница самостоятельной сумки в этом наборе не доказаны.'),
143201:('≈ Аксиллярная складка капсулы · IGHL',14302,'ligaments','Нижняя складка капсулы между плечевой шейкой и нижним краем суставной впадины; в растянутом состоянии образует U-образный аксиллярный карман. Это часть полости сустава, а не самостоятельная сумка. Цветная лента обозначает ожидаемый ход капсулы; без растяжения жидкостью нельзя достоверно сегментировать стенку и просвет.'),
143202:('≈ IGHL · передний пучок',14302,'ligaments','Передний пучок нижнего суставно-плечевого комплекса: от передненижней губы/края суставной впадины к нижней части анатомической шейки плеча. Формирует передний край аксиллярного кармана. Ориентир поставлен на кососагиттальных PD; отдельные волокна на этих JPEG уверенно не прослеживаются. Не заменяет МР-артрографическую оценку.'),
143203:('≈ IGHL · задний пучок',14302,'ligaments','Задний пучок IGHL: от задненижнего края суставной впадины/губы к задненижней части анатомической шейки плеча. Формирует задний край аксиллярного кармана. Отмечена ожидаемая топография на кососагиттальных PD, а не доказанный контур волокон.'),
143204:('≈ Аксиллярная капсула · лопаточная часть',14302,'ligaments','Лопаточная часть нижней капсулы: прилежит к нижнему краю суставной впадины и губе, продолжается к нижней складке. На фронтальном срезе это медиальная сторона кармана. Ориентир не является точной границей энтезиса; повреждение здесь относится к гленоидной стороне комплекса.'),
143205:('≈ Аксиллярная капсула · плечевая часть',14302,'ligaments','Плечевая часть нижней капсулы и ожидаемая зона её прикрепления к нижней области анатомической шейки. На фронтальном срезе это латеральная сторона кармана. Прикрепление вариабельно: описаны воротникообразный и V-образный варианты. Ориентир не означает патологию или доказанную авульсию.'),
143206:('≈ Аксиллярный карман · нижняя складка',14302,'ligaments','Нижняя переходная складка капсулы между её лопаточной и плечевой частями. Между передним и задним пучками IGHL лежит аксиллярная часть капсулы. В приведённой руке складка спавшаяся; показана учебная область, не просвет и не объём жидкости.')}
frames={s['sourceSeries']:s for s in D['series'] if s['id'].endswith('_dp')};series={s['id']:{} for s in frames.values()}
def frame(se,n):
 s=frames[se];return series[s['id']].setdefault(s['frames'][n-1]['annotation'],{'points':[],'regions':[],'suppress':[2380,2384]})
def region(se,n,sid,vs,width=5):
 name,g,cat,note=ST[sid];frame(se,n)['regions'].append(dict(structure=sid,name=name,filter=g,category=cat,approximate=True,vertices=vs,width=width))
